  async function runFinanceAction(action,button){let path,body={},label=action;try{if(!state.company)throw new Error("X-Company-ID wajib diisi.");if(action==="billing-verify"){path=`/api/v1/commands/finance/billing-documents/${selected("billing-verify")}/verify/`;label="Verify billing"}else if(action==="billing-approve"){path=`/api/v1/commands/finance/billing-documents/${selected("billing-approve")}/approve/`;label="Approve billing"}else if(action==="billing"){path=`/api/v1/commands/finance/billing-documents/${selected("billing")}/post/`;label="Post billing"}else if(action==="payment-submit"){path=`/api/v1/commands/finance/payments/${selected("payment-submit")}/submit/`;label="Submit payment"}else if(action==="payment-approve"){path=`/api/v1/commands/finance/payments/${selected("payment-approve")}/approve/`;label="Approve payment"}else if(action==="payment-execute"){path=`/api/v1/commands/finance/payments/${selected("payment-execute")}/execute/`;label="Execute payment";const executionReference=document.getElementById("flow-execution-reference")?.value.trim();if(!executionReference)throw new Error("Referensi transaksi bank/kas wajib diisi.");body={execution_reference:executionReference,note:"Dieksekusi dari Finance Operational Flow"}}else if(action==="payment"){path=`/api/v1/commands/finance/payments/${selected("payment")}/allocate/`;label="Allocate payment";body={allocations:[{billing_document_id:selected("allocation-billing"),allocated_amount:String(document.getElementById("flow-allocation-amount")?.value||"")}]} }else if(action==="statement"){path=`/api/v1/commands/finance/bank-statements/${selected("statement")}/reconcile/`;label="Reconcile bank statement";body={matches:[]}}else if(action==="journal"){path=`/api/v1/commands/finance/journal-entries/${selected("journal")}/post/`;label="Post journal"}else if(action==="period-close"){path=`/api/v1/commands/finance/fiscal-periods/${selected("period")}/close/`;label="Close period";body={force:false,closing_type:"MONTHLY"}}else if(action==="period-reopen"){path=`/api/v1/commands/finance/fiscal-periods/${selected("period")}/reopen/`;label="Reopen period";body={reason:"Finance Flow validation"}}else if(action==="budget"){path=`/api/v1/commands/finance/budgets/${selected("budget")}/check/`;label="Budget check";body={account_id:selected("account"),period_number:Number(document.getElementById("flow-budget-period").value),requested_amount:String(document.getElementById("flow-budget-amount").value)}}else if(action==="kpi"){path="/api/v1/commands/analytics/kpis/recalculate/";label="KPI recalculate";const filters=jsonOrThrow(document.getElementById("flow-kpi-filters").value,"Filters harus JSON object valid.");if(!filters||Array.isArray(filters)||typeof filters!=="object")throw new Error("Filters harus berupa JSON object.");body={kpi_definition_id:selected("kpi"),company_id:state.company,filters}}else{throw new Error(`Aksi finance tidak dikenali: ${action}.`)}button.disabled=true;button.textContent="Menjalankan…";await requestJSON(path,{method:"POST",body});toast(`${label} berhasil`,"Data accounting diperbarui.","success");await loadFinanceData()}catch(error){toast(`${label} gagal`,error.message,"error")}finally{renderAccountingWorkspace()}}

