  async function loadPMBackend(force=false){if(state.pm.loading||state.offline||!state.access)return;if(state.pm.loaded&&!force)return;state.pm.loading=true;state.pm.error="";if(force)renderProjectManagementV2();try{const paths={projects:"/api/v1/projects/projects/?page_size=200",tasks:"/api/v1/projects/tasks/?page_size=500",milestones:"/api/v1/projects/milestones/?page_size=300",controls:"/api/v1/projects/control-items/?page_size=500",expenses:"/api/v1/projects/expenses/?page_size=500",members:"/api/v1/projects/members/?page_size=500",timesheets:"/api/v1/projects/timesheets/?page_size=500",users:"/api/v1/accounts/users/?page_size=200",billings:FINANCE_SOURCES.billings};const data=Object.fromEntries(await Promise.all(Object.entries(paths).map(async([k,path])=>{try{return[k,normalizeList(await requestJSON(path,{method:"GET"})).rows]}catch{return[k,[]]}})));state.finance.data.billings=data.billings;state.pm.members=data.members||[];state.pm.timesheets=data.timesheets||[];state.pm.users=data.users||[];state.pm.projects=data.projects.map(row=>{const p={...row,id:row.id,code:row.project_code,name:row.project_name,customer:row.customer_party||"-",manager:row.project_manager||displayName(state.user),status:row.status||row.lifecycle_status||"PLANNED",health:row.health_status||"UNKNOWN",progress:Number(row.progress_percent||0),budget:Number(row.budget_amount||0),actual:0,start:row.planned_start_date,end:row.planned_end_date,description:row.description||"",resources:0,materials:0,risks:0,issues:0,qa:0,documents:0,tasks:{total:0,done:0,blocked:0},milestones:{total:0,done:0},workItems:{tasks:[],timeline:[],resources:[],risk:[],quality:[],documents:[]},expenses:[],members:[],timesheets:[]};p.members=(data.members||[]).filter(m=>String(m.project)===String(p.id));p.timesheets=(data.timesheets||[]).filter(t=>String(t.project)===String(p.id));p.workItems.tasks=data.tasks.filter(x=>String(x.project)===String(p.id)).map(x=>({id:x.id,title:x.task_name,owner:x.assigned_to||p.manager,status:x.status||"PLANNED",date:(x.planned_end_at||"").slice(0,10),weight:Number(x.weight_percent||0),progress:Number(x.progress_percent||0),description:"",apiType:"tasks"}));p.workItems.timeline=data.milestones.filter(x=>String(x.project)===String(p.id)).map(x=>({id:x.id,title:x.milestone_name,owner:x.owner_user||p.manager,status:x.status||"PLANNED",date:x.planned_date,weight:Number(x.weight_percent||0),progress:String(x.status).toUpperCase()==="DONE"?100:0,description:"",apiType:"milestones"}));data.controls.filter(x=>String(x.project)===String(p.id)).forEach(x=>{const type={RESOURCE:"resources",RISK:"risk",QUALITY:"quality",DOCUMENT:"documents"}[x.item_type];if(type)p.workItems[type].push({id:x.id,title:x.title,owner:x.owner_name,status:x.status,date:x.target_date,weight:Number(x.quantity||0),description:x.description,updatedBy:x.updated_by||"Backend",apiType:"control-items"})});p.expenses=data.expenses.filter(x=>String(x.project)===String(p.id)).map(x=>({id:x.id,title:x.title,category:x.category,vendor:x.vendor_name,date:x.expense_date,amount:Number(x.amount||0),billingId:x.billing_document,description:x.description,paymentStatus:x.payment_status,invoiceNumber:x.billing_invoice_number}));syncPMWeightedStats(p);syncPMExpenses(p);p.resources=p.workItems.resources.length;p.risks=p.workItems.risk.length;p.qa=p.workItems.quality.length;p.documents=p.workItems.documents.length;return p});state.pm.live=true;state.pm.loaded=true;if(!state.pm.projects.some(x=>x.id===state.pm.selectedId))state.pm.selectedId=state.pm.projects[0]?.id||""}catch(error){state.pm.error=error.message;state.pm.loaded=true;state.pm.live=false}finally{state.pm.loading=false;renderProjectManagementV2()}}
  function loadPMState(){if(state.access&&!state.offline&&!state.pm.loaded){loadPMBackend();return}if(state.pm.projects.length)return;if(state.access&&!state.offline&&state.pm.error)return;try{state.pm.projects=JSON.parse(localStorage.getItem(PM_STORE)||"null")||structuredClone(PM_SEED)}catch{state.pm.projects=structuredClone(PM_SEED)}state.pm.projects.forEach(ensurePMStructure);state.pm.selectedId=state.pm.projects[0]?.id||""}
